const float* nn_forward(float input[INPUT_SIZE]) {
    // Input normalization
    for (int i = 0; i < INPUT_SIZE; i++) {
        mlp.scaled_input[i] = (((input[i]-mlp.X_mins[i])/(mlp.X_maxs[i]-mlp.X_mins[i]))-0.5f)*2.f;
    }
    // Forward
    layer(19, 24, mlp.scaled_input, mlp.layers_0_weight, mlp.layers_0_bias, mlp.layers_0_activation, 2);
    layer(24, 24, mlp.layers_0_activation, mlp.layers_2_weight, mlp.layers_2_bias, mlp.layers_2_activation, 2);
    layer(24, 24, mlp.layers_2_activation, mlp.layers_4_weight, mlp.layers_4_bias, mlp.layers_4_activation, 2);
    layer(24, 6, mlp.layers_4_activation, mlp.layers_6_weight, mlp.layers_6_bias, mlp.layers_6_activation, 0);
    // Output normalization
    for (int i = 0; i < OUTPUT_SIZE; i++) {
        mlp.scaled_output[i] = (mlp.layers_6_activation[i] + 1.f) * 0.5f * (mlp.y_maxs[i] - mlp.y_mins[i]) + mlp.y_mins[i];
    }
    return mlp.scaled_output;
};
